    n = len(s)

    def count_partitions(t: str) -> int:
        """Count the number of partitions for string t."""
        count = 0
        i = 0
        while i < len(t):
            count += 1
            seen = set()
            while i < len(t) and (len(seen) < k or t[i] in seen):
                if t[i] not in seen:
                    seen.add(t[i])
                    if len(seen) > k:
                        break
                i += 1
        return count

    # Base case: no change
    best = count_partitions(s)

    # Try changing each position to each possible character
    for i in range(n):
        original = s[i]
        for c in 'abcdefghijklmnopqrstuvwxyz':
