    # If there's any 1 and n > 1, return False unless all are 1... but even then they're not connected
    # Wait, if all are 1, then no two distinct indices can be traversed between, so return False for n > 1
    has_one = any(x == 1 for x in nums)
    if has_one and n > 1:
        # If there's a 1, it's isolated. For the graph to be connected with n > 1,
        # every pair must be connected. Since 1 can't connect to anything, return False
        return False

    # Union-Find approach
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
