def maximumSum(nums: List[int]) -> int:
    import math
    from collections import defaultdict

    def get_square_free(n: int) -> int:
        """Return the square-free part of n (product of primes with odd exponents)."""
        if n == 1:
            return 1
        result = 1
        count = 0
        while n % 2 == 0:
            n //= 2
            count += 1
        if count % 2 == 1:
            result *= 2
        f = 3
        while f * f <= n:
            count = 0
            while n % f == 0:
                n //= f
                count += 1
            if count % 2 == 1:
                result *= f
            f += 2
        if n > 1:
            result *= n
        return result

    groups = defaultdict(list)
    for num in nums:
        sf = get_square_free(num)
        groups[sf].append(num)

    max_sum = 0
    for sf, group in groups.items():
        total = sum(group)
        if total > max_sum:
            max_sum = total

    return max_sum
